$_MODULE['<{retractationcommande}prestashop>demande_3a6a3681876ab1e4c55fdecb70fab698'] = 'Die Nachricht enthält unzulässige Zeichen.';
$_MODULE['<{retractationcommande}prestashop>demande_0f9a15225078e2688ee78b984640f46d'] = 'Angeforderte Menge übersteigt die widerrufbare Menge.';
$_MODULE['<{retractationcommande}prestashop>demande_36c075970e7709b21dc06b19cb75c19e'] = 'Wählen Sie mindestens ein zu widerrufendes Produkt aus.';
$_MODULE['<{retractationcommande}prestashop>demande_b0998d501f75050aa4045d17399c25d0'] = 'Der Antrag konnte nicht gespeichert werden. Bitte wenden Sie sich an den Kundenservice.';
$_MODULE['<{retractationcommande}prestashop>demande_9914a2c75cdd71876e656e7621e47300'] = 'Ihr Widerruf wurde unter der Referenz %s registriert. Eine Empfangsbestätigung wurde Ihnen per E-Mail zugesandt. Unser Kundenservice wird Ihren Antrag prüfen und Ihnen das Rücksendeverfahren übermitteln.';
$_MODULE['<{retractationcommande}prestashop>demande_049d1d68c945230da39359dbd32e1d48'] = 'Ihr Widerruf wurde unter der Referenz %s registriert. Eine Empfangsbestätigung wurde Ihnen per E-Mail zugesandt. Da Ihre Bestellung bereits versandt wurde, können Sie das Paket bei der Zustellung verweigern oder, falls Sie es erhalten, das Rücksendeverfahren befolgen, das Ihnen unser Kundenservice zusendet.';
$_MODULE['<{retractationcommande}prestashop>demande_f49c93cbb2dab9d8c4b41d7e8a0f346d'] = 'Ihr Widerruf wurde unter der Referenz %s registriert. Eine Empfangsbestätigung wurde Ihnen per E-Mail zugesandt. Da Ihre Bestellung noch nicht versandt wurde, ist keine Rücksendung erforderlich: Nach der Prüfung wird der Versand storniert und Sie erhalten eine Rückerstattung.';
$_MODULE['<{retractationcommande}prestashop>demande_5a06e6b127a7d1baaf18d35bde389969'] = 'Unser Kundenservice prüft die Voraussetzungen Ihres Antrags (gesetzliche Frist von 14 Tagen, Ausschlüsse gemäß Artikel L221-28). Bei Konformität wird Ihnen das Rücksendeverfahren per E-Mail übermittelt, anschließend erfolgt die Rückerstattung spätestens 14 Tage nach Erhalt der Ware oder des Versandnachweises. Bitte senden Sie das Produkt nicht zurück, bevor Sie das Rücksendeverfahren erhalten haben.';
$_MODULE['<{retractationcommande}prestashop>demande_b91f8258aeb37ba358b04427913bd6b1'] = 'Zu prüfen: 14-Tage-Frist, gesetzliche Ausschlüsse (Art. L221-28), bereits zurückgesandte Produkte.';
$_MODULE['<{retractationcommande}prestashop>demande_869cbd236cf583ec668d9f90469f561c'] = 'Ihre Bestellung wurde bereits versandt und befindet sich auf dem Transportweg. Sie können das Paket bei der Zustellung verweigern; falls Sie es erhalten, öffnen Sie es nicht und warten Sie auf das Rücksendeverfahren, das Ihnen unser Kundenservice nach Prüfung zusendet. Die Rückerstattung erfolgt spätestens 14 Tage nach Erhalt der Ware oder des Nachweises ihrer Rücksendung.';
$_MODULE['<{retractationcommande}prestashop>demande_e32237222087921238a826c436916179'] = 'BESTELLUNG VERSANDT (unterwegs) — das Paket ist abgegangen: Paketverweigerung oder Rücksendung einplanen. Zu prüfen: gesetzliche Ausschlüsse (Art. L221-28). Die 14-Tage-Frist beginnt erst mit der Lieferung.';
$_MODULE['<{retractationcommande}prestashop>demande_ba6e3c755dec44b85c76f4e9e919450b'] = 'Da Ihre Bestellung noch nicht versandt wurde, ist keine Rücksendung erforderlich. Nach Prüfung Ihres Antrags durch unseren Kundenservice wird der Versand storniert und Ihnen der gesamte gezahlte Betrag spätestens 14 Tage nach Ihrem Antrag über dasselbe Zahlungsmittel erstattet (Art. L221-24).';
$_MODULE['<{retractationcommande}prestashop>demande_ecbc815f858a7d4a0ff0fe67f6eea2a3'] = 'NICHT VERSANDTE BESTELLUNG — Stornierung vor Versand: keine Produktrücksendung zu erwarten. Zu prüfen: gesetzliche Ausschlüsse (Art. L221-28). Denken Sie daran, den Versand vor der Bestätigung zu sperren.';
$_MODULE['<{retractationcommande}prestashop>demande_00e9581137cc9fcce29afdb92e74d13a'] = 'Versandt, unterwegs';
$_MODULE['<{retractationcommande}prestashop>demande_5f0d073c461f238ea2622dc70766a38f'] = 'Zum Zeitpunkt des Antrags nicht versandt';
$_MODULE['<{retractationcommande}prestashop>demande_a860874ff76e61887b36e2c13ab146f1'] = 'Empfangsbestätigung Ihres Widerrufsantrags';
$_MODULE['<{retractationcommande}prestashop>demande_cb082ed668c8c616513cef755d589f79'] = 'Neuer zu prüfender Widerrufsantrag';
$_MODULE['<{retractationcommande}prestashop>pdf-droits_f9598f3efc5b2b93bd2643a72a431969'] = 'Sie haben 14 Tage Zeit, um vom Vertrag zurückzutreten, ohne Angabe von Gründen (Art. L221-18 des französischen Verbrauchergesetzbuchs). Die Frist beginnt am Tag nach der Lieferung der Ware (oder nach Vertragsschluss bei einer Dienstleistung). Endet sie an einem Samstag, Sonntag oder Feiertag, verlängert sie sich bis zum nächsten Werktag.';
$_MODULE['<{retractationcommande}prestashop>pdf-droits_5aea05f1d39a0423c4b25484d0bfbbfb'] = 'Waren, die nach der Lieferung entsiegelt wurden und aus Gründen der Hygiene oder des Gesundheitsschutzes nicht zurückgegeben werden können;';
$_MODULE['<{retractationcommande}prestashop>pdf-droits_44fc39e9f72aa3cbac9747645c8e3f28'] = 'digitale Inhalte, die nicht auf einem körperlichen Datenträger geliefert werden und deren Ausführung mit Ihrer Zustimmung begonnen hat;';
$_MODULE['<{retractationcommande}prestashop>pdf-droits_b6ecb45483f4b3b9de90c6b3d7e2086c'] = 'Waren, die nach der Lieferung untrennbar mit anderen Artikeln vermischt wurden.';
$_MODULE['<{retractationcommande}prestashop>pdf-droits_ea20d48829cf42f58a7ba2e8d2ccab41'] = 'Unser Kundendienst prüft Ihren Antrag und sendet Ihnen anschließend das Rücksendeverfahren per E-Mail zu. Bitte senden Sie die Ware nicht zurück, bevor Sie dieses erhalten haben, und geben Sie die Ware vollständig und im Originalzustand zurück.';
$_MODULE['<{retractationcommande}prestashop>pdf-droits_c7c5d3c287928163baae28c1c94ffb57'] = 'Bestellung bereits versandt: Sie können das Paket bei der Zustellung ablehnen. Falls Sie es annehmen, öffnen Sie es nicht und folgen Sie dem Rücksendeverfahren, das Ihnen unser Kundendienst zusendet. Geben Sie die Ware vollständig und im Originalzustand zurück.';
$_MODULE['<{retractationcommande}prestashop>pdf-droits_ad7b6dc631e43afbd497f23ef43ab78c'] = 'Bestellung nicht versandt: Eine Rücksendung der Ware ist nicht erforderlich. Unser Kundendienst prüft Ihren Antrag, storniert den Versand und erstattet den Betrag.';
$_MODULE['<{retractationcommande}prestashop>pdf-droits_7d1c4561845314f94d407ede430c9a60'] = 'Wenn Sie der Ansicht sind, dass Ihr Antrag nicht ordnungsgemäß bearbeitet wurde, können Sie sich an unseren Kundendienst wenden und anschließend kostenlos eine Verbraucherschlichtungsstelle anrufen (Art. L612-1 des französischen Verbrauchergesetzbuchs).';
$_MODULE['<{retractationcommande}prestashop>pdf-bon-retour_447b937c6e82f11f7c6f842ebf73a9fb'] = 'Rücksendeschein';
$_MODULE['<{retractationcommande}prestashop>pdf-bon-retour_ee5418842e4f1cc41001743702c53b90'] = 'Auszudrucken und außen auf das Paket zu kleben. Ohne diesen Schein kann Ihre Rücksendung von unserer Logistik nicht angenommen werden.';
$_MODULE['<{retractationcommande}prestashop>pdf-bon-retour_577d7068826de925ea2aec01dbadf5e4'] = 'Kunde';
