$_MODULE['<{retractationcommande}prestashop>pdf-bon-retour_af31f4375e6cb5fbec556bafaf5e5fc2'] = 'Automatisch erstelltes Dokument — Kundendienst';
$_MODULE['<{retractationcommande}prestashop>pdf-accuse_11a3f4d6e53bd65481fadea719f7186d'] = 'Rücksendeadresse';
$_MODULE['<{retractationcommande}prestashop>pdf-accuse_afe72c2b21191da1897798ce03f6bb0a'] = 'Gemäß Artikel L221-21 des französischen Verbrauchergesetzbuchs bestätigen wir den Eingang Ihres Widerrufs';
$_MODULE['<{retractationcommande}prestashop>pdf-accuse_1d4a33337550b1d60f155dc7dca2ecef'] = 'Ihr Antrag wird von unserem Kundendienst geprüft (Einhaltung der gesetzlichen Frist, Ausnahmen nach Artikel L221-28 des französischen Verbrauchergesetzbuchs). Ist er ordnungsgemäß, erhalten Sie das Rücksendeverfahren per E-Mail. Bitte senden Sie die Ware nicht zurück, bevor Sie dieses erhalten haben. Die Erstattung erfolgt spätestens 14 Tage nach Erhalt der Ware oder nach Vorlage des Versandnachweises, über dasselbe Zahlungsmittel wie bei der Bestellung (Art. L221-24). Die unmittelbaren Kosten der Rücksendung tragen Sie (Art. L221-23).';
$_MODULE['<{retractationcommande}prestashop>pdf-accuse_08a4255076063ff093392602b74f2dde'] = 'Da Ihre Bestellung zum Zeitpunkt Ihres Antrags bereits versandt war, können Sie das Paket bei der Zustellung ablehnen oder, falls Sie es annehmen, dem Rücksendeverfahren folgen, das Ihnen unser Kundendienst nach der Prüfung zusendet (Ausnahmen nach Artikel L221-28 des französischen Verbrauchergesetzbuchs). Die Erstattung erfolgt spätestens 14 Tage nach Erhalt der Ware oder nach Vorlage des Rücksendenachweises, über dasselbe Zahlungsmittel wie bei der Bestellung (Art. L221-24). Die unmittelbaren Kosten der Rücksendung tragen Sie (Art. L221-23).';
$_MODULE['<{retractationcommande}prestashop>pdf-accuse_ecd429447c2c5c11827567f6c066424e'] = 'Da Ihre Bestellung zum Zeitpunkt Ihres Antrags noch nicht versandt war, ist keine Rücksendung erforderlich. Nach Prüfung durch unseren Kundendienst (Ausnahmen nach Artikel L221-28 des französischen Verbrauchergesetzbuchs) wird der Versand storniert und der gesamte gezahlte Betrag spätestens 14 Tage nach Ihrem Antrag über dasselbe Zahlungsmittel wie bei der Bestellung erstattet (Art. L221-24).';
$_MODULE['<{retractationcommande}prestashop>formulaire_6fd32367e8a01032b6c24770df162923'] = 'Gemäß Artikel L221-18 ff. des französischen Verbrauchergesetzbuchs haben Sie';
$_MODULE['<{retractationcommande}prestashop>formulaire_04f75f9992b78fd3affb67c8db773850'] = 'ab dem Tag nach der Lieferung Zeit, um ohne Angabe von Gründen zu widerrufen. Endet diese Frist an einem Samstag, Sonntag oder Feiertag, verlängert sie sich bis zum nächsten Werktag.';
$_MODULE['<{retractationcommande}prestashop>formulaire_8cac0c691d545cd91a37c8e8e044d328'] = 'Sie haben';
$_MODULE['<{retractationcommande}prestashop>formulaire_9f4000c0f036a4e4d1d5d03aab0c7eef'] = 'ab der Lieferung Zeit, um eine Rücksendung zu beantragen.';
$_MODULE['<{retractationcommande}prestashop>formulaire_f00d6e0ec96b82767e8b675d300fd9ab'] = 'Ihre für eine Rücksendung infrage kommenden Bestellungen';
$_MODULE['<{retractationcommande}prestashop>formulaire_7727eb7488be3ef30da590f1f667181e'] = 'Rücksendung';
