$_MODULE['<{retractationcommande}prestashop>formulaire_8e768a03b00a269f26e6cb5a6213b24f'] = 'Derzeit kommt keine Ihrer Bestellungen für einen Widerruf infrage (gesetzliche Frist abgelaufen oder Bestellungen nicht betroffen).';
$_MODULE['<{retractationcommande}prestashop>formulaire_c1ce181667f69ea149cb0a425ccdb21e'] = 'Derzeit kommt keine Ihrer Bestellungen für eine Rücksendung infrage (Frist abgelaufen oder Bestellungen nicht betroffen).';
$_MODULE['<{retractationcommande}prestashop>formulaire_24eabc929ddb3eb38fd6cf81b5ffa805'] = 'Geben Sie die bei der Bestellung verwendete E-Mail-Adresse und die Bestellreferenz ein (in Ihrer Bestellbestätigung enthalten).';
$_MODULE['<{retractationcommande}prestashop>formulaire_b414b1464d384d5b827c361fec76cc8f'] = 'Diese Bestellung kommt für einen Online-Widerruf nicht (mehr) infrage: gesetzliche Frist abgelaufen, Antrag bereits gestellt oder Bestellung nicht betroffen. Bei Fragen wenden Sie sich bitte an unseren Kundendienst.';
$_MODULE['<{retractationcommande}prestashop>formulaire_dbad83ecebaf719a4dd60e45bbec0e03'] = 'Das Widerrufsrecht gilt nicht für bestimmte Verträge (Art. L221-28 des französischen Verbrauchergesetzbuchs: nach Kundenspezifikation angefertigte oder personalisierte Waren, verderbliche Waren, aus Hygienegründen entsiegelte Waren usw.). Nach dem Absenden wird Ihr Antrag von unserem Kundendienst geprüft, der Ihnen das Rücksendeverfahren zusendet. Die Erstattung erfolgt spätestens 14 Tage nach Erhalt der Ware oder nach Vorlage des Versandnachweises über dasselbe Zahlungsmittel. Die Kosten der Rücksendung tragen Sie.';
$_MODULE['<{retractationcommande}prestashop>modal_30e7d78f70861e0332aa4cbb81a2fcd3'] = 'Rücksendung möglich';
$_MODULE['<{retractationcommande}prestashop>modal_dd3b9e7bb6b5077d2235d0d84a518e91'] = 'Zu Händen von';
