$_MODULE['<{retractationcommande}prestashop>modal_217c9acbe7666448db6b898ca2ab6bef'] = 'Rücksendeantrag bestätigen';
$_MODULE['<{retractationcommande}prestashop>modal_810a3d382ec684c35146d332e396e1c1'] = 'Mit der Bestätigung wird Ihr Widerruf an unseren Kundendienst übermittelt und Sie erhalten per E-Mail eine Empfangsbestätigung mit einem PDF-Exemplar (Art. L221-21 des französischen Verbrauchergesetzbuchs). Nach Prüfung der Voraussetzungen (gesetzliche Frist, Ausnahmen nach Art. L221-28) erhalten Sie das Rücksendeverfahren — bitte senden Sie die Artikel nicht zurück, bevor Sie dieses erhalten haben. Die Erstattung erfolgt spätestens 14 Tage nach Erhalt der Ware oder nach Vorlage des Versandnachweises (bei vollständigem Widerruf einschließlich Lieferkosten, andernfalls anteilig). Die Kosten der Rücksendung tragen Sie.';
$_MODULE['<{retractationcommande}prestashop>modal_abeaaec30c11df72742faf07dc857200'] = 'Mit der Bestätigung wird Ihr Widerruf an unseren Kundendienst übermittelt und Sie erhalten per E-Mail eine Empfangsbestätigung mit einem PDF-Exemplar (Art. L221-21 des französischen Verbrauchergesetzbuchs). Da Ihre Bestellung bereits versandt wurde, können Sie das Paket bei der Zustellung ablehnen; falls Sie es annehmen, öffnen Sie es nicht und folgen Sie dem Rücksendeverfahren, das Ihnen unser Kundendienst zusendet. Die Erstattung erfolgt spätestens 14 Tage nach Erhalt der Ware oder nach Vorlage des Rücksendenachweises. Die Kosten der Rücksendung tragen Sie.';
$_MODULE['<{retractationcommande}prestashop>modal_ad52dcb5592e9f635028ab04aaf1fcec'] = 'Mit der Bestätigung wird Ihr Widerruf an unseren Kundendienst übermittelt und Sie erhalten per E-Mail eine Empfangsbestätigung mit einem PDF-Exemplar (Art. L221-21 des französischen Verbrauchergesetzbuchs). Da Ihre Bestellung noch nicht versandt wurde, ist keine Rücksendung erforderlich: Nach der Prüfung (Ausnahmen nach Art. L221-28) wird der Versand storniert und der gesamte gezahlte Betrag spätestens 14 Tage nach Ihrem Antrag über dasselbe Zahlungsmittel erstattet.';
$_MODULE['<{retractationcommande}prestashop>modal_c729999c38ef8dd3345cdcab0b29495a'] = 'Mit der Bestätigung wird Ihr Rücksendeantrag an unseren Kundendienst übermittelt, der ihn anhand unserer Rücknahmebedingungen prüft und Ihnen das weitere Vorgehen mitteilt. Bitte senden Sie die Artikel nicht zurück, bevor Sie dieses erhalten haben.';
$_MODULE['<{retractationcommande}prestashop>order-detail_5d6cad579ad55412b4c2f0e3e412a87a'] = 'Sie haben eine gesetzliche Frist von 14 Tagen für den Widerruf';
