$_MODULE['<{retractationcommande}prestashop>demande_56cbaaf41017fdf11adb876a6219ba51'] = 'Der Antrag konnte nicht gespeichert werden. Bitte wenden Sie sich an den Kundendienst.';
$_MODULE['<{retractationcommande}prestashop>demande_afeb49c5004af7a5c3fb574552f8524f'] = 'Ihr Rücksendeantrag wurde unter der Referenz %s erfasst. Eine Bestätigung wurde Ihnen per E-Mail zugesandt. Unser Kundendienst prüft Ihren Antrag und sendet Ihnen das Rücksendeverfahren zu.';
$_MODULE['<{retractationcommande}prestashop>demande_81e83ee9703e6ffae031e8e2eded2a35'] = 'Ihr Widerruf wurde unter der Referenz %s erfasst. Eine Empfangsbestätigung wurde Ihnen per E-Mail zugesandt. Da Ihre Bestellung noch nicht versandt wurde, ist keine Rücksendung erforderlich: Nach der Prüfung wird der Versand storniert und Ihnen der Betrag erstattet.';
$_MODULE['<{retractationcommande}prestashop>demande_9f4095725b4314c97caefc7cc2bf5f14'] = 'Unser Kundendienst prüft Ihren Antrag anhand unserer Rücknahmebedingungen. Wird er angenommen, erhalten Sie das Rücksendeverfahren per E-Mail. Bitte senden Sie den Artikel nicht zurück, bevor Sie dieses erhalten haben.';
$_MODULE['<{retractationcommande}prestashop>demande_50b76525f8ad63640702a5c148f36e5c'] = 'KULANZRÜCKSENDUNG (Regeln der Kundengruppe) — anhand Ihrer Rücknahmebedingungen zu prüfen, nicht anhand des Widerrufsrechts.';
$_MODULE['<{retractationcommande}prestashop>demande_1808dee14b88dac577384c0f22c5926e'] = 'Unser Kundendienst prüft, ob Ihr Antrag zulässig ist (gesetzliche Frist von 14 Tagen, Ausnahmen nach Artikel L221-28). Ist er ordnungsgemäß, erhalten Sie das Rücksendeverfahren per E-Mail; die Erstattung erfolgt anschließend spätestens 14 Tage nach Erhalt der Ware oder nach Vorlage des Versandnachweises. Bitte senden Sie den Artikel nicht zurück, bevor Sie das Rücksendeverfahren erhalten haben.';
$_MODULE['<{retractationcommande}prestashop>demande_5b3514e1541cfd0318e31c694a2aa909'] = 'Ihre Bestellung wurde bereits versandt und ist unterwegs. Sie können das Paket bei der Zustellung ablehnen; falls Sie es annehmen, öffnen Sie es nicht und warten Sie auf das Rücksendeverfahren, das Ihnen unser Kundendienst nach der Prüfung zusendet. Die Erstattung erfolgt spätestens 14 Tage nach Erhalt der Ware oder nach Vorlage des Rücksendenachweises.';
$_MODULE['<{retractationcommande}prestashop>demande_fef84e875177fa1aa360bef363059b72'] = 'BESTELLUNG VERSANDT (unterwegs) — das Paket ist raus: Paketablehnung oder Rücksendung einplanen. Zu prüfen: gesetzliche Ausnahmen (Art. L221-28). Die 14-Tage-Frist beginnt erst mit der Lieferung.';
$_MODULE['<{retractationcommande}prestashop>demande_e1a266b5d2d6ad5263f80d3a3cb670b3'] = 'Da Ihre Bestellung noch nicht versandt wurde, ist keine Rücksendung erforderlich. Nach Prüfung Ihres Antrags durch unseren Kundendienst wird der Versand storniert und der gesamte gezahlte Betrag spätestens 14 Tage nach Ihrem Antrag über dasselbe Zahlungsmittel erstattet (Art. L221-24).';
